def compact(n: int) -> str:
    from decimal import Decimal, ROUND_HALF_UP

    d = Decimal(n).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)
    if d == 0:
        return '0'

    value = float(d)
    if value < 1000:
        return ('%d' % int(value)) if value.is_integer() else ('%g' % value)

    if value < 1_000_000:
        unit, scaled = 'mil', value / 1000
    elif value < 1_000_000_000:
        unit, scaled = 'mi', value / 1_000_000
    else:
        unit, scaled = 'bi', value / 1_000_000_000

    scaled = Decimal(scaled).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)
    if scaled == scaled.to_integral_value():
        return '%d %s' % (int(scaled), unit)
    return '%g %s' % (scaled, unit)
