def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not weights:
        raise ValueError("weights must be non-empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not contain negative values")
    if all(w == 0 for w in weights):
        raise ValueError("weights must not be all zero")

    total = sum(weights)
    result = [total_cents * w // total for w in weights]
    leftover = total_cents - sum(result)

    for i, w in enumerate(weights):
        if leftover <= 0:
            break
        remainder = (total_cents * w) % total
        if remainder >= leftover:
            result[i] += 1
            leftover -= 1

    return result
