def build_order(deps: dict[str, list[str]]) -> list[str]:
    import heapq

    # Collect all items (both keys and items that appear only as dependencies)
    items = set(deps.keys())
    for item in deps:
        for dep in deps[item]:
            items.add(dep)

    # Build adjacency list and compute in-degrees
    # An edge from dependency -> item means: dependency must come first
    adj: dict[str, list[str]] = {item: [] for item in items}
    indegree: dict[str, int] = {item: 0 for item in items}

    for item, item_deps in deps.items():
        for dep in item_deps:
            adj[dep].append(item)
            indegree[item] += 1

    # Start with all items that have no dependencies, in alphabetical order
    ready = [item for item in items if indegree[item] == 0]
    heapq.heapify(ready)

    order: list[str] = []

    while ready:
        # Take the alphabetically smallest ready item
        current = heapq.heappop(ready)
        order.append(current)

        for nxt in adj[current]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)

    # If not all items were processed, there is a cycle
    if len(order) != len(items):
        raise ValueError("cycle detected")

    return order
```

