def build_order(deps: dict[str, list[str]]) -> list[str]:
    graph = {}
    for item, dependencies in deps.items():
        graph[item] = list(dependencies)
        for dependency in dependencies:
            graph.setdefault(dependency, [])

    visited = {}
    order = []

    def visit(node):
        state = visited.get(node)
        if state == "visiting":
            raise ValueError("cycle detected")
        if state == "done":
            return
        visited[node] = "visiting"
        for dependency in graph[node]:
            visit(dependency)
        visited[node] = "done"
        order.append(node)

    ready = sorted(graph.keys())
    while ready:
        ready.sort()
        node = ready.pop(0)
        if visited.get(node) == "done":
            continue
        visit(node)
        for dependency in graph[node]:
            if visited.get(dependency) == "done":
                ready.append(dependency)
                ready.sort()

    return order
