def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not contain negative values")
    if all(w == 0 for w in weights):
        raise ValueError("weights must not all be zero")

    total = sum(weights)

    if total == 1:
        return [total_cents]

    base = total_cents // total
    remainder = total_cents % total

    allocated = [base * w for w in weights]
    result = list(allocated)

    parts = sorted(enumerate(weights), key=lambda x: (x[1] % total, -x[0]))

    for i in range(remainder):
        index, _ = parts[i]
        result[index] += 1

    return result
