        s = s[1:]

    s = s.replace('R$', '').replace(' ', '')

    if not s:
        raise ValueError(s)

    if s[0] == ',':
        raise ValueError(s)

    if s[-1] in '.,':
        raise ValueError(s)

    digits = ''.join(ch for ch in s if ch.isdigit())
    separators = s.replace(',', '').replace('.', '')

    if digits != separators:
        raise ValueError(s)

    if not digits:
        raise ValueError(s)

    if ',' in s:
        int_part, cents = s.split(',')
        if len(cents) != 2 or not cents.isdigit():
            raise ValueError(s)
    else:
        int_part, cents = s, ''

    if int_part != digits:
        raise ValueError(s)

    if negative:
        return Decimal('-' + digits + cents)
    return Decimal(digits + cents)
