from typing import List

def build_order(deps: dict[str, list[str]]) -> List[str]:
    graph: dict[str, set[str]] = {k: set(v) for k, v in deps.items()}
    for node, children in graph.items():
        for child in children:
            graph.setdefault(child, set()).add(node)

    indegree = {node: len(children) for node, children in graph.items()}

    heap = [node for node, d in indegree.items() if d == 0]
    heapq.heapify(heap)

    order: List[str] = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for nxt in sorted(graph[node]):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(graph):
        raise ValueError("cycle detected")

    return order
