def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.split("\n")
    result = lines[:]
    changed = False

    for i, line in enumerate(lines):
        stripped = line.strip()
        if not stripped or stripped[0] in (';', '#'):
            continue
        if not stripped.startswith("[") or not stripped.endswith("]"):
            continue
        header = stripped[1:-1].strip()
        if header != section:
            continue
        # Split on first '=' only
        if "=" not in line:
            continue
        left, _, right = line.partition("=")
        lkey = left.strip()
        if lkey == key:
            result[i] = f"{key} = {value}"
            changed = True
            break

    if not changed:
        raise KeyError(f"section={section!r} or key={key!r} not found")

    return "\n".join(result)
