def is_woodall(n):
    """Check if n is a Woodall number.

    A Woodall number is a number of the form n * 2^n - 1 for some positive integer n.
    """
    if n < 1:
        return False
    for k in range(1, n + 2):
        if k * (2 ** k) - 1 == n:
            return True
    return False
